INSERT INTO _e VALUES
 ('ENT_SCI_COSMOLOGY','Scientology Cosmology','concept','belief-system','Scientology','cosmology','B','Hub collective for the cosmological belief-entities of Scientology, a practiced modern new religion; the framework of thetans, body thetans, and the OT-level space-opera narratives held within the tradition.'),
 ('ENT_SCI_THETAN','Thetan','spirit','soul','Scientology','soul / immortal spirit','B','In Scientology belief, the thetan is the immortal spiritual being that each person fundamentally is, having lived through countless past lives; a core devotional/doctrinal concept central to auditing practice.'),
 ('ENT_SCI_BODY_THETAN','Body Thetans','spirit','spirit','Scientology','disembodied spirits','C','In the advanced (OT III) belief held by practicing Scientologists, body thetans are disembodied thetans (from the Xenu/Incident II account) clustered on the body, addressed in auditing; modeled neutrally as a sincerely-held esoteric belief.'),
 ('ENT_SCI_XENU','Xenu','figure','mythic-ruler','Scientology','galactic ruler','C','In the OT III "Incident II" cosmogony taught within Scientology, Xenu is the galactic ruler said to have brought billions of thetans to Earth ~75 million years ago; modeled neutrally as a belief-entity of the tradition.'),
 ('ENT_SCI_MARCAB','Marcab Confederacy','place','otherworld','Scientology','galactic civilization','C','In Scientology''s auditing cosmology, the Marcab Confederacy is an ancient interstellar civilization recalled in past-life accounts; modeled neutrally as a belief-entity held within the tradition.');
